import org.junit.jupiter.api.Assertions.*
import kotlin.test.Test
import org.example.NeedlemanWunsch

class NeedlemanWunschTest {
    // Use Optimize for somewhat similar sequences @ https://blast.ncbi.nlm.nih.gov/Blast.cgi?PROGRAM=blastn&BLAST_SPEC=GeoBlast&PAGE_TYPE=BlastSearch

    val genomeSnippet = ""
    val targetGenome = ""
    val testAgainst = ""

    @Test
    fun perfectMatch() {
        val nw = NeedlemanWunsch(matchScore = 1, mismatchScore = -2, gapScore = -2)
        val r = nw.align("ACGT", "ACGT")
        assertEquals("ACGT", r.alignedA)
        assertEquals("ACGT", r.alignedB)
        assertEquals(4, r.score)
    }

    @Test
    fun simpleGap() {
        val nw = NeedlemanWunsch()
        val r = nw.align("ACGT", "AGT")
        assertEquals(r.alignedA.length, r.alignedB.length)
    }

    @Test
    fun alignmentSequences() {
        val nw = NeedlemanWunsch()
        val result = nw.align(genomeSnippet, testAgainst)

        assertEquals(
            result.alignedA.length,
            result.alignedB.length
        )

        assertTrue(
            result.score > 0
        )
    }
}